import java.io.*;
import java.util.Arrays;

public class Main {
    private static int[] parent;
    private static int[] sz;

    private static int find(int x) {
        int r = x;
        while (parent[r] != r) r = parent[r];
        while (parent[x] != r) {
            int nx = parent[x];
            parent[x] = r;
            x = nx;
        }
        return r;
    }

    private static byte[] buf;
    private static int ptr = 0;
    private static int len = 0;

    private static void readAll(InputStream is) throws IOException {
        ByteArrayOutputStream bos = new ByteArrayOutputStream(1 << 22);
        byte[] chunk = new byte[1 << 16];
        int r;
        while ((r = is.read(chunk)) != -1) bos.write(chunk, 0, r);
        buf = bos.toByteArray();
        len = buf.length;
    }

    private static int nextInt() {
        while (ptr < len && (buf[ptr] < '0' || buf[ptr] > '9')) ptr++;
        int ret = 0;
        while (ptr < len && buf[ptr] >= '0' && buf[ptr] <= '9') {
            ret = ret * 10 + (buf[ptr] - '0');
            ptr++;
        }
        return ret;
    }

    public static void main(String[] args) throws IOException {
        readAll(System.in);
        int N = nextInt();
        int M = nextInt();

        int[] eu = new int[M];
        int[] ev = new int[M];
        int[] deg = new int[N + 1];
        for (int i = 0; i < M; i++) {
            int x = nextInt();
            int y = nextInt();
            eu[i] = x;
            ev[i] = y;
            deg[x]++;
            deg[y]++;
        }

        // CSR (lista de adjacência compacta)
        int[] off = new int[N + 2];
        for (int v = 1; v <= N; v++) off[v + 1] = off[v] + deg[v];
        int[] fill = Arrays.copyOf(off, N + 2);
        int[] adj = new int[2 * M];
        for (int i = 0; i < M; i++) {
            adj[fill[eu[i]]++] = ev[i];
            adj[fill[ev[i]]++] = eu[i];
        }

        // DSU para componentes conexas
        parent = new int[N + 1];
        sz = new int[N + 1];
        for (int i = 1; i <= N; i++) {
            parent[i] = i;
            sz[i] = 1;
        }
        for (int i = 0; i < M; i++) {
            int a = find(eu[i]);
            int b = find(ev[i]);
            if (a != b) {
                if (sz[a] < sz[b]) {
                    int t = a;
                    a = b;
                    b = t;
                }
                parent[b] = a;
                sz[a] += sz[b];
            }
        }

        // Informações por componente (indexadas pela raiz)
        int[] comp = new int[N + 1];
        int[] compSize = new int[N + 1];
        int[] minDeg = new int[N + 1];
        int[] argmin = new int[N + 1];
        Arrays.fill(minDeg, Integer.MAX_VALUE);
        for (int v = 1; v <= N; v++) {
            int r = find(v);
            comp[v] = r;
            compSize[r]++;
            if (deg[v] < minDeg[r]) {
                minDeg[r] = deg[v];
                argmin[r] = v;
            }
        }

        // Uma aresta (A,B) é redundante <=> A e B já estão na mesma componente.
        // Além disso (A,B) não pode existir. Então buscamos, dentro de alguma
        // componente, dois vértices não adjacentes.
        // Se a componente tem tamanho k >= 3 e não é um clique, o vértice u de grau
        // mínimo da componente tem grau < k-1, logo existe não-vizinho v na própria
        // componente (todas as arestas são internas à componente).
        int[] ts = new int[N + 1];
        int timer = 0;
        String ans = null;

        for (int r = 1; r <= N && ans == null; r++) {
            if (parent[r] != r) continue;          // não é raiz de componente
            if (compSize[r] < 3) continue;         // tamanho 1 ou 2: sem par válido
            if (minDeg[r] >= compSize[r] - 1) continue; // é um clique: sem par válido

            int u = argmin[r];
            timer++;
            for (int j = off[u]; j < off[u + 1]; j++) ts[adj[j]] = timer;

            for (int x = 1; x <= N; x++) {
                if (comp[x] != r || x == u) continue;
                if (ts[x] != timer) {              // x está na componente e não é vizinho de u
                    ans = u + " " + x;
                    break;
                }
            }
        }

        StringBuilder sb = new StringBuilder();
        sb.append(ans == null ? "-1" : ans).append('\n');
        System.out.print(sb);
    }
}
